import math
from scipy.integrate import quad, dblquad


def circulation(P, Q, x, y, dx, dy, a, b):
    def g(t):
        X, Y = x(t), y(t)
        return P(X, Y) * dx(t) + Q(X, Y) * dy(t)
    return quad(g, a, b, limit=200)[0]


def curl_integral_polar(curl, r_max, theta0, theta1):
    f = lambda r, th: curl(r * math.cos(th), r * math.sin(th)) * r
    return dblquad(f, theta0, theta1, lambda th: 0, lambda th: r_max)[0]
